samples.code:
token, err := agent.MintToken() // the current agent token, renewed before it expires
if err != nil {
	t.Fatal(err)
}
req, err := http.NewRequestWithContext(ctx, http.MethodGet, resURL+"/api/documents", nil)
if err != nil {
	t.Fatal(err)
}
aauth.AttachSignatureKey(req, token) // Signature-Key: sig=jwt;jwt="..."
if err := aauth.SignRequest(req, agent.Key, ""); err != nil {
	t.Fatal(err) // Signature-Input and Signature over method, authority, path and Signature-Key
}
res, err := hc.Do(req)
if err != nil {
	t.Fatal(err)
}

// The signature proves the request comes from the key in cnf.jwk of
// the agent token; the token, signed by the agent provider, says
// which agent holds that key.
agent, err := aauth.VerifyAndExtractAgent(r.Context(), r, aauth.VerifyAgentTokenOptions{
	Resolver: a.resolver, // agent provider keys, discovered from the token's iss
})
if err != nil {
	aauth.WriteSignatureFailure(w, err) // 401 with Signature-Error
	return
}
// Decide on the agent: here, any agent from one provider's domain.
if !strings.HasSuffix(agent.Subject, "@agent.example") {
	aauth.WriteProblem(w, http.StatusForbidden, aauth.ErrCodeInvalidRequest, "unknown agent")
	return
}
respondJSON(w, map[string]string{"agent": agent.Subject, "documents": "plan.md, notes.md"})

claims, err := aauth.VerifyAgentToken(ctx, issued.AgentToken, aauth.VerifyAgentTokenOptions{
	Resolver: aauth.NewJWKSResolver(hc), // the provider's keys, from its metadata
})
if err != nil {
	t.Fatal(err)
}
id, err := aauth.ParseAgentIdentifier(claims.Subject)
if err != nil {
	t.Fatal(err)
}
// The agent signs with its own key and presents tokens from the
// provider, renewed before they expire.
agent, err := aauth.NewAgent(id, aauth.WithKey(key), aauth.WithPersonServer(claims.PS),
	aauth.WithTokenSource(apc.TokenSource(func(ctx context.Context) (*agentprovider.TokenResponse, error) {
		return apc.Issue(ctx, key, enrollment)
	})))
if err != nil {
	t.Fatal(err)
}

// The provider signs agent tokens with its own key, never an agent's.
key, err := aauth.GenerateKey(aauth.AlgEd25519)
if err != nil {
	t.Fatal(err)
}
ap, err := agentprovider.New(agentprovider.Config{
	Issuer:     issuer,
	Domain:     "agent.example", // agent identifiers are aauth:<name>@agent.example
	Key:        key,
	Registrar:  enrollments{ps: ps}, // decides which agent each key is
	HTTPClient: hc,
})
if err != nil {
	t.Fatal(err)
}

key, err := aauth.GenerateKey(aauth.AlgEd25519) // or a key held in a platform keystore
if err != nil {
	t.Fatal(err)
}
apc := &agentprovider.Client{BaseURL: apURL, HTTPClient: hc}
enrollment := map[string]string{"device": "laptop-42"}
// Issue signs the request with the new key under the hwk scheme.
issued, err := apc.Issue(ctx, key, enrollment)
if err != nil {
	t.Fatal(err)
}

var body struct {
	Device string `json:"device"`
}
if err := json.Unmarshal(req.Body, &body); err != nil || body.Device == "" {
	return nil, errors.New("enrollment names the device")
}
// A stable local part per install (bootstrap §6), and the person
// server this agent works with, carried as the ps claim.
return &agentprovider.Registration{Name: "assistant-" + body.Device, PS: e.ps}, nil

p, err := w.ps.ConsumeCodeFor(r.Context(), r.URL.Query().Get("code"), r.RemoteAddr)
if err != nil {
	http.Error(rw, "this link has expired or was already used", http.StatusBadRequest)
	return
}
// The code only links this browser to the request: authenticate the
// person before acting on their decision.
person, ok := signedInPerson(r)
if !ok {
	http.Error(rw, "sign in first", http.StatusUnauthorized)
	return
}
// After showing what the agent asks for, record the approval.
if err := w.ps.Approve(r.Context(), p.ID, personserver.Grant{Person: person}); err != nil {
	http.Error(rw, err.Error(), http.StatusConflict)
	return
}

// When the PS defers for the person, show them where to go. The
// client keeps polling while they decide.
psc.OnRequirement = func(r aauth.Requirement) {
	if r.Requirement != aauth.RequirementInteraction {
		return
	}
	link := r.URL + "?code=" + url.QueryEscape(r.Code)
	showUser(w, link, r.Code) // open a browser, or print the link and code
}

// The PS asks the person before granting access. Deferring with
// requirement=interaction answers 202 with Location, the
// interaction URL and a single-use code; the agent polls Location
// while the person decides at the URL.
if r.ResourceToken == nil || r.Scope == "" {
	return personserver.Deny("no scope requested")
}
return personserver.DeferInteraction()

// The pending URL is polled with GET, re-signed each time. Prefer:
// wait asks the PS to hold each poll open until something changes,
// rather than answering at once with another 202.
psc.PreferWaitSeconds = 10

// The PS has verified the agent and the person; the AS applies the
// resource's own policy to the resource token the PS sent on.
if r.Resource.Scope != "documents:read" {
	return accessserver.Deny("only read access is offered"), nil
}
// Allow issues the auth token that goes back to the PS.
return accessserver.Allow(r.Resource.Scope), nil

// The PS sends a resource token addressed to an access server on to
// that server, signing the request under jwks_uri with its own key.
fed := accessserver.NewClient(ps.Signer(), hc)
fed.PreferWaitSeconds = 10 // long-poll when the AS defers
return fed

cfg := personserver.Config{
	Issuer:     issuer,
	Key:        key,
	SubjectKey: subjectKey,
	Store:      personserver.NewMemoryStore(),
	Decider: personserver.DeciderFunc(func(_ context.Context, r *personserver.TokenRequest) (personserver.Decision, error) {
		if r.Kind == personserver.KindPersonToken {
			return decidePersonToken(r), nil
		}
		return decideAuthToken(r), nil
	}),
	InteractionURL: issuer + "/consent", // the page that calls ConsumeCode and Approve
	Federator:      fed,                 // auth tokens for resources that chose an access server
	HTTPClient:     hc,
}

req, err := http.NewRequestWithContext(ctx, http.MethodGet, resURL+"/api/documents", nil)
if err != nil {
	t.Fatal(err)
}
// Present the person token instead of the agent token: it names the
// person and carries the agent's key, so the same signature works.
aauth.AttachSignatureKey(req, personToken)
if err := aauth.SignRequest(req, agent.Key, ""); err != nil {
	t.Fatal(err)
}
res, err := hc.Do(req)
if err != nil {
	t.Fatal(err)
}

// The person token is addressed to this resource and bound to the
// key that signed the request.
person, err := aauth.VerifyAndExtractPerson(r.Context(), r, p.url, p.verify)
if err != nil {
	aauth.WriteSignatureFailure(w, err)
	return
}
// sub is unique within its PS only: key the person's record by both.
if !p.trusted[person.Issuer] {
	aauth.WriteProblem(w, http.StatusForbidden, aauth.ErrCodeInvalidRequest, "person server not accepted")
	return
}
respondJSON(w, map[string]string{"ps": person.Issuer, "person": person.Subject})

// A person token is issued for one resource: it becomes the token's
// aud. The client signs the request with the agent token and caches
// the result until shortly before it expires.
personToken, err := psc.PersonToken(ctx, aauth.PersonTokenRequest{Resource: resourceURL})
if err != nil {
	t.Fatal(err)
}

// The person token says which person the agent acts for. This PS
// enrolled the agent from alice's signed-in session, so an agent it
// has not bound yet is bound to her; a bound agent keeps its person.
if r.Person == "" {
	return personserver.Allow(personserver.Grant{Person: "alice"})
}
return personserver.Allow(personserver.Grant{})

req, err = http.NewRequestWithContext(ctx, http.MethodGet, res.url+"/api/documents", nil)
if err != nil {
	t.Fatal(err)
}
aauth.AttachSignatureKey(req, at.AuthToken) // present the auth token
if err := aauth.SignRequest(req, agent.Key, ""); err != nil {
	t.Fatal(err)
}
apiRes, err := hc.Do(req)
if err != nil {
	t.Fatal(err)
}

claims, err := aauth.VerifyAndExtractAuth(r.Context(), r, d.url, aauth.AuthTokenVerifyOptions{
	TokenVerifyOptions: d.verify,
	// Accept tokens only from the server this resource's tokens name,
	// and key the person's record by (iss, sub).
	CheckSubject: func(_ context.Context, iss, _ string) error {
		if iss != d.audience {
			return fmt.Errorf("%w: unexpected issuer %s", aauth.ErrInvalidToken, iss)
		}
		return nil
	},
})
if err != nil {
	aauth.WriteSignatureFailure(w, err) // 401 with Signature-Error
	return
}
if !strings.Contains(" "+claims.Scope+" ", " documents:read ") {
	aauth.WriteProblem(w, http.StatusForbidden, aauth.ErrCodeInvalidScope, "documents:read is required")
	return
}
respondJSON(w, map[string]any{"owner": claims.Subject, "documents": []string{"plan.md", "notes.md"}})

// Redeem the resource token with the token presented to get it, and
// say the agent can bring the person in. The call follows 202
// responses while the person decides.
at, err := psc.RequestAuthToken(ctx, aauth.AuthTokenRequest{
	ResourceToken:     ar.ResourceToken,
	PresentedToken:    personToken,
	TokenRequestHints: aauth.TokenRequestHints{Capabilities: []string{aauth.CapabilityInteraction}},
})
if err != nil {
	t.Fatal(err)
}

// Check the auth token before presenting it: issued by the server the
// resource token named, for this resource, bound to this agent's key.
granted, err := aauth.VerifyAuthTokenResponse(ctx, at.AuthToken, aauth.AuthResponseVerifyOptions{
	TokenVerifyOptions: w.verify, Resource: rc, Agent: agent, Presented: personToken,
})
if err != nil {
	t.Fatal(err)
}
t.Logf("granted %q until %v", granted.Scope, granted.ExpiresAt)

body, err := json.Marshal(aauth.AuthorizeRequest{Scope: "documents:read"})
if err != nil {
	t.Fatal(err)
}
req, err := http.NewRequestWithContext(ctx, http.MethodPost, res.url+"/authorize", bytes.NewReader(body))
if err != nil {
	t.Fatal(err)
}
req.Header.Set("Content-Type", "application/json")
aauth.AttachSignatureKey(req, personToken) // present the person token
if err := aauth.SignRequest(req, agent.Key, ""); err != nil {
	t.Fatal(err) // signs with a Content-Digest of the body
}
authRes, err := hc.Do(req)
if err != nil {
	t.Fatal(err)
}

// The handler verifies the person token and the request signature,
// then asks Decide. The resource token it returns names the server
// that decides: the agent's PS, or this resource's access server.
return &aauth.AuthorizationHandler{
	Resource: d.url,
	Verify:   d.verify, // the PS's keys, discovered from its metadata
	Decide: func(_ context.Context, _ *http.Request, person *aauth.PersonClaims, ar aauth.AuthorizeRequest) (aauth.AuthorizeDecision, error) {
		if ar.Scope != "documents:read" {
			return aauth.AuthorizeDecision{}, &aauth.ProblemError{Status: http.StatusBadRequest, Code: aauth.ErrCodeInvalidScope}
		}
		rt, err := aauth.IssueResourceToken(aauth.ResourceTokenParams{
			Resource: d.url, Audience: d.audience, Scope: ar.Scope,
		}, person, d.key, d.jwk.Kid)
		return aauth.AuthorizeDecision{ResourceToken: rt}, err
	},
}

var ar aauth.AuthorizeResponse
if authRes.StatusCode != http.StatusOK {
	t.Fatalf("authorize: %s", authRes.Status)
}
if err := json.NewDecoder(authRes.Body).Decode(&ar); err != nil {
	t.Fatal(err)
}
// Check the resource token before sending it to the PS: issued by
// this resource, for this agent's key, this PS and this person.
rc, err := aauth.VerifyResourceChallenge(ctx, ar.ResourceToken, aauth.ResourceChallengeOptions{
	TokenVerifyOptions: w.verify, Resource: res.url, Agent: agent, PS: agent.PS, Presented: personToken,
})
if err != nil {
	t.Fatal(err)
}

code, err := interactioncode.Canonicalize(r.URL.Query().Get("code"))
person, signedIn := signedInPerson(r) // the resource's own login
if err != nil || !signedIn {
	http.Error(w, "sign in and use the code your agent showed you", http.StatusBadRequest)
	return
}
l.mu.Lock()
defer l.mu.Unlock()
for _, p := range l.pending {
	if c, err := interactioncode.Canonicalize(p.code); err == nil && c == code && p.session == "" {
		// The person approved: the session belongs to this agent's key.
		p.session = randomToken()
		l.sessions[p.session] = p.agentJKT
		respondJSON(w, map[string]string{"approved_by": person})
		return
	}
}
http.Error(w, "unknown or used code", http.StatusBadRequest)

// A 202 with requirement=interaction: show the person the URL and
// code, and poll Location, re-signing each poll, until the resource
// answers.
opts := aauth.DeferredOptions{
	Sign:                sign,
	DefaultPollInterval: time.Second,
	OnRequirement: func(r aauth.Requirement) {
		if r.Requirement == aauth.RequirementInteraction {
			openBrowser(w, r.URL+"?code="+url.QueryEscape(r.Code))
		}
	},
}

// Only an agent that declared the interaction capability can bring
// the person here.
if !aauth.CanRaise(r, aauth.RequirementInteraction) {
	aauth.WriteProblem(w, http.StatusForbidden, aauth.TokenErrUserUnreachable, "the person must approve this agent")
	return
}
code, err := interactioncode.Generate()
if err != nil {
	aauth.WriteProblem(w, http.StatusInternalServerError, aauth.ErrCodeServerError, "")
	return
}
id := randomToken()
l.mu.Lock()
l.pending[id] = &approvalRequest{code: code, agentJKT: agent.Cnf.JWK.Thumbprint()}
l.mu.Unlock()
// 202 with Location to poll, and the URL and code for the person.
aauth.ChainInteraction(w, l.url+"/pending/"+id, l.url+"/interact", code)

final, err := aauth.FollowDeferred(ctx, hc, req.URL, res, opts)
if err != nil {
	t.Fatal(err)
}

req, err := http.NewRequestWithContext(ctx, http.MethodGet, resURL+"/api/ledger", nil)
if err != nil {
	t.Fatal(err)
}
// Declare that the agent can bring the person to an interaction URL.
caps, err := aauth.FormatCapabilities([]string{aauth.CapabilityInteraction})
if err != nil {
	t.Fatal(err)
}
req.Header.Set(aauth.HeaderCapabilities, caps)
if err := sign(req); err != nil { // agent token in Signature-Key, then sign
	t.Fatal(err)
}
res, err := hc.Do(req)
if err != nil {
	t.Fatal(err)
}

agent, err := aauth.VerifyAndExtractAgent(r.Context(), r, aauth.VerifyAgentTokenOptions{Resolver: l.resolver})
if err != nil {
	aauth.WriteSignatureFailure(w, err)
	return
}
// A request carrying a session token this resource issued is served;
// any other asks the person first.
if session := r.Header.Get(aauth.HeaderAAuthAccess); session != "" {
	l.serveSession(w, session, agent)
	return
}
l.requireInteraction(w, r, agent)

req, err = http.NewRequestWithContext(ctx, http.MethodGet, resURL+"/api/ledger", nil)
if err != nil {
	t.Fatal(err)
}
req.Header.Set(aauth.HeaderAAuthAccess, session) // covered by the signature
if err := sign(req); err != nil {
	t.Fatal(err)
}
res, err = hc.Do(req)
if err != nil {
	t.Fatal(err)
}

// The session token is only good with the key it was issued to; the
// signature covers AAuth-Access, so it cannot be moved to another
// request.
l.mu.Lock()
jkt, ok := l.sessions[session]
l.mu.Unlock()
if !ok || jkt != agent.Cnf.JWK.Thumbprint() {
	aauth.WriteProblem(w, http.StatusUnauthorized, aauth.ErrCodeInvalidRequest, "unknown session")
	return
}
respondJSON(w, map[string]any{"entries": []string{"2026-10-01 coffee 4.50"}})

var authorized aauth.AuthorizeResponse
if err := json.NewDecoder(final.Body).Decode(&authorized); err != nil {
	t.Fatal(err)
}
closeBody(t, final)
// Keep the session token for later calls; a newer AAuth-Access on any
// response replaces it.
session := final.Header.Get(aauth.HeaderAAuthAccess)
if final.StatusCode != http.StatusOK || session == "" {
	t.Fatalf("%s %+v without a session token", final.Status, authorized)
}
